function ProfitAndLossStatement()
local RES= teamyar.query(context,[[{"query":"with recursive CTE_Account AS (SELECT ID as SourceAccount,ID as AccountID, CODE AS AccountCode, PARENT , ORG_ID AS ORG_ID FROM pa_account WHERE ORG_ID = 1 UNION SELECT  CTE_Account.SourceAccount as SourceAccount,pa.ID as AccountID, pa.CODE AS AccountCode, pa.PARENT , pa.ORG_ID AS ORG_ID FROM CTE_Account INNER JOIN pa_account as pa ON CTE_Account.AccountID = pa.PARENT and CTE_Account.ORG_ID = pa.ORG_ID), cte_DateRangePerYear as (select min(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) as sdate,  max(DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) edate, JYEAR FROM REPORT_DIMDATE where (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) <= 133553537990000000)) OR (((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000)) <= 132922818000000000) AND ((DATEKEY - MOD( 126000000000+ DATEKEY ,864000000000) +828000000000+35400000000+590000000) >= 133553537990000000)) group by JYEAR), CTE_VoucherRecords as  (select cte_DateRangePerYear.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID,SUM(COALESCE(pvr.CRD, 0) - COALESCE(pvr.DEB, 0)) as remain from cte_DateRangePerYear inner join pa_voucher as pv on pv.RUN_DATE >= sdate and pv.RUN_DATE <= edate inner join pa_voucher_record as pvr on pv.ID = pvr.VOUCHER_ID and pv.ORG_ID = pvr.ORG_ID where pv.ORG_ID = 1 and (pv.RUN_DATE >=132922818000000000 and pv.RUN_DATE <= 133552800000000000) and pv.type in (1,4,5) and pv.status in(2,4,5,6) and pv.deleted = 0 and pvr.deleted = 0 group by cte_DateRangePerYear.JYEAR,pv.ORG_ID,pvr.ACCOUNT_ID) ,CTE_AccountsVouchersInfo AS (select CTE_Account.SourceAccount,CTE_Account.ORG_ID,sum(CTE_VoucherRecords.remain) as remain,CTE_VoucherRecords.JYEAR from CTE_Account left join CTE_VoucherRecords on CTE_Account.AccountID=CTE_VoucherRecords.ACCOUNT_ID and CTE_Account.ORG_ID=CTE_VoucherRecords.ORG_ID group by CTE_Account.SourceAccount,CTE_Account.ORG_ID,CTE_VoucherRecords.JYEAR), CTE_OPIncomeAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 1 as type from CTE_AccountsVouchersInfo where SourceAccount in(185,186) group by ORG_ID,JYEAR), CTE_TCOPIncomeAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 2 as type from CTE_AccountsVouchersInfo where SourceAccount in(203,204) group by ORG_ID,JYEAR) ,CTE_GeneralCostAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 4 as type from CTE_AccountsVouchersInfo where SourceAccount in(241) group by ORG_ID,JYEAR), CTE_DecValCostsAccounts as(select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 5 as type from CTE_AccountsVouchersInfo where SourceAccount in(2053,2084,2413,2493) group by ORG_ID,JYEAR), CTE_OtherIncAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 6 as type from CTE_AccountsVouchersInfo where SourceAccount in(189) group by ORG_ID,JYEAR), CTE_OtherCostsAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 7 as type from CTE_AccountsVouchersInfo where SourceAccount in(275) group by ORG_ID,JYEAR), CTE_FinCostsAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 9 as type from CTE_AccountsVouchersInfo where SourceAccount in(257) group by ORG_ID,JYEAR), CTE_OtherNonOPAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 10 as type from CTE_AccountsVouchersInfo where SourceAccount in(293) group by ORG_ID,JYEAR ), CTE_TaxCostsAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 12 as type from CTE_AccountsVouchersInfo where SourceAccount in(2054,2055,2209,2489) group by ORG_ID,JYEAR), CTE_StopOPAccounts as (select ORG_ID, sum(COALESCE(remain,0)) as remain, JYEAR, 15 as type from CTE_AccountsVouchersInfo where SourceAccount in(2319) group by ORG_ID,JYEAR), cte_UnionRemainAccounts as(select ORG_ID, remain , JYEAR, type from CTE_OPIncomeAccounts Union All select ORG_ID, remain, JYEAR, type from CTE_TCOPIncomeAccounts Union All select ORG_ID, remain, JYEAR, type from  CTE_GeneralCostAccounts Union All select  ORG_ID, remain, JYEAR, type from  CTE_DecValCostsAccounts Union All select  ORG_ID, remain, JYEAR, type from  CTE_OtherIncAccounts Union All select  ORG_ID, remain, JYEAR, type  from CTE_OtherCostsAccounts Union All select  ORG_ID, remain, JYEAR, type from  CTE_FinCostsAccounts Union All select  ORG_ID, remain, JYEAR, type from  CTE_OtherNonOPAccounts Union All select  ORG_ID, remain, JYEAR, type from CTE_TaxCostsAccounts Union All select  ORG_ID, remain, JYEAR, type  from CTE_StopOPAccounts), CTE_GrossProfit as (select  ORG_ID, sum(remain) as remain, JYEAR, 3 as type from cte_UnionRemainAccounts where type in(1,2) group by ORG_ID, JYEAR) , CTE_OperationProfit as (select  ORG_ID, sum(remain) as remain, JYEAR, 8 as type from cte_UnionRemainAccounts where type>= 1 And type <= 7 group by ORG_ID, JYEAR), CTE_OPProfitBeforTax as (select  ORG_ID, sum(remain) as remain, JYEAR, 11 as type from cte_UnionRemainAccounts where type not in(12,13,15) group by  ORG_ID, JYEAR), CTE_PureOperationProfit as (select  ORG_ID, sum(remain) as remain, JYEAR, 14 as type from cte_UnionRemainAccounts where type not in(15) group by ORG_ID, JYEAR), CTE_PureProfit as (select  ORG_ID, sum(remain) as remain, JYEAR, 16 as type from cte_UnionRemainAccounts where type<= 15 group by ORG_ID, JYEAR), CTE_OpProfitPerUnit as (select  ORG_ID, sum(COALESCE(remain,0)) /COALESCE(4 , 1) as remain, JYEAR, 20 as type from cte_UnionRemainAccounts where type<= 15 group by  ORG_ID, JYEAR), CTE_NonOpProfitPerUnit as (select  c1.ORG_ID, (sum(COALESCE(c1.remain,0)) /COALESCE(4 , 1)) - (sum(COALESCE(c2.remain,0))) as remain, c1.JYEAR, 21 as type from cte_UnionRemainAccounts c1 left join cte_UnionRemainAccounts c2 on c1.ORG_ID = c2.ORG_ID and c1.JYEAR = c2.JYEAR where c1.type<=15 and c2.type = 12 group by  c1.ORG_ID, c1.JYEAR), cte_CurrOpProfitPerUnit as ( select  c1.ORG_ID,sum(COALESCE(c1.remain,0)) + sum(COALESCE(c2.remain,0)) as remain,c1.JYEAR, 22 as type from  CTE_OpProfitPerUnit c1 left join CTE_NonOpProfitPerUnit c2 on c1.ORG_ID = c2.ORG_ID and c1.JYEAR = c2.JYEAR group by  c1.ORG_ID, c1.JYEAR), CTE_StopOpProfitPerUnit as (select  ORG_ID, sum(COALESCE(remain,0)) /COALESCE(4 , 1) as remain, JYEAR, 23 as type from cte_UnionRemainAccounts where type= 15 group by  ORG_ID, JYEAR), CTE_ProfitPerUnit as (select  c1.ORG_ID, (sum(COALESCE(c1.remain,0)) + sum(COALESCE(c2.remain,0)) + sum(COALESCE(c3.remain,0)) + sum(COALESCE(c4.remain,0)))  as remain, c1.JYEAR, 24 as type from CTE_OpProfitPerUnit c1 left join CTE_NonOpProfitPerUnit c2 on c1.ORG_ID = c2.ORG_ID and c1.JYEAR = c2.JYEAR left join cte_CurrOpProfitPerUnit c3 on c3.ORG_ID = c2.ORG_ID and c3.JYEAR = c2.JYEAR left join CTE_StopOpProfitPerUnit c4 on c3.ORG_ID = c4.ORG_ID and c3.JYEAR = c4.JYEAR group by  c1.ORG_ID, c1.JYEAR), cte_DecimalCount as (select ps.ORG_ID,ps.ID,ps.name,ps.DECIMAL_COUNT,ps.FEE_DECIMAL from PA_ORGANIZATIONS as po inner join PA_SYMBOLS as ps on po.BASE_CURRENCY = ps.id and po.ORG_ID = ps.ORG_ID), Cte_RemainAccounts as(select  ORG_ID, remain , JYEAR, type from cte_UnionRemainAccounts UNION All select  ORG_ID, remain , JYEAR, type from  CTE_GrossProfit UNION All select  ORG_ID, remain , JYEAR, type from  CTE_OperationProfit UNION All select  ORG_ID, remain , JYEAR, type from  CTE_OPProfitBeforTax UNION All select  ORG_ID, remain , JYEAR, type from  CTE_PureOperationProfit UNION All select  ORG_ID, remain , JYEAR, type from  CTE_PureProfit UNION All select  ORG_ID, remain , JYEAR, type from  CTE_OpProfitPerUnit UNION All select  ORG_ID, remain , JYEAR, type from  CTE_NonOpProfitPerUnit UNION All select  ORG_ID, remain , JYEAR, type from  cte_CurrOpProfitPerUnit UNION All select  ORG_ID, remain , JYEAR, type from  CTE_StopOpProfitPerUnit UNION All select  ORG_ID, remain , JYEAR, type from  CTE_ProfitPerUnit), Cte_RemainAccountsBaseDecimalCount as (select cra.ORG_ID,oi.NAME as OrgName,  COALESCE(cra.remain, 0)/POWER(10, COALESCE(cdc.DECIMAL_COUNT, 0)) as remain , cra.JYEAR, cra.type  from Cte_RemainAccounts cra left join cte_DecimalCount cdc on cra.ORG_ID = cdc.ORG_ID left join org_info oi on cra.ORG_ID = oi.ID) select JSON_ARRAYAGG(JSON_OBJECT( 'ORG_ID',ORG_ID, 'OrgName',OrgName,'type',type,'JYEAR',JYEAR,'YEAR',IF(JYEAR =0,'',concat('سال',' ',JYEAR)), 'remain',remain, 'title',CASE COALESCE(type,0)  WHEN 1 THEN 'درآمدهای عملیاتی' WHEN 2 THEN 'بهای تمام شده درآمدهای عملیاتی' WHEN 3 THEN 'سود ناخالص' WHEN 4 THEN 'هزینه های فروش،  اداری و عمومی' WHEN 5 THEN 'زیان کاهش ارزش دریافتنی ها' WHEN 6 THEN 'سایر درآمدها'  WHEN 7 THEN 'سایر هزینه ها' WHEN 8 THEN 'سود عملیاتی' WHEN 9 THEN 'هزینه های مالی' WHEN 10 THEN 'سایر درآمدها و هزینه های غیرعملیاتی' WHEN 11 THEN 'سود عملیات در حال تداوم قبل از مالیات' WHEN 12 THEN 'هزینه مالیات بر درآمد'  WHEN 14 THEN 'سود خالص عملیات در حال تداوم' WHEN 15 THEN 'سود خالص عملیات متوقف شده' WHEN 16 THEN 'سود خالص' WHEN 20 THEN 'عملیاتی (ریال)'  WHEN 21 THEN 'غیر عملیاتی (ریال)'  WHEN 22 THEN 'ناشی از عملیات در حال تداوم (ریال)'  WHEN 23 THEN 'ناشی از عملیات متوقف شده (ریال)' WHEN 24 THEN 'سود پایه هر سهم (ریال)' ELSE '--'  END)) as result from Cte_RemainAccountsBaseDecimalCount  where JYEAR>=0 order by JYEAR ASC,type;","params":[]}]]);
teamyar.write_result(context,RES)
end

ProfitAndLossStatement()